-- 0354 PROD CHECK (before-0354), read-only, ONE statement: npx --yes supabase@2.120.0 db query --linked -f scripts/ops/harness/fleet-room/before-0354.sql
-- Wanted (head 0353): every hunk old_times 1 and new_times 0; made: every value null (nothing of 0354 is there); fleet_room_bite false; house_room_rows 0; slot_word null; ord_56_is null; removed_kinds []; premises all true.
-- Generated by scripts/ops/harness/fleet-room/gen-checks-0354.mjs from the migration's own hunks. Every function called is STABLE or IMMUTABLE; no game function is called (world.fleets() is read as text only).
begin transaction read only;
with h(fn, ord, old, new) as (values
  ('world.fleets()'::text, 1, $h$    'ships', (select coalesce(jsonb_agg(world.ship_view(s.id)   -- 0124: one ship, one builder
                 order by s.is_flagship desc, s.name), '[]'::jsonb)
                 from public.ships s
                where s.fleet_id = f.id),
$h$, $h$    'ships', sv.ships,   -- 0354: built once, in the lateral below, so the totals are sums of these very reads
    'totals', public.fleet_totals(f.id, sv.ships),   -- 0354: what the fleet adds up to (docs/FLEETS_AND_SLOTS.md section 2.5)
$h$),
  ('world.fleets()'::text, 2, $h$    from public.fleets f where f.player_id = v_player);
$h$, $h$    from public.fleets f
   cross join lateral (select coalesce(jsonb_agg(world.ship_view(s.id)   -- 0124: one ship, one builder
                 order by s.is_flagship desc, s.name), '[]'::jsonb) as ships
                 from public.ships s
                where s.fleet_id = f.id offset 0) sv   -- 0354: OFFSET 0 keeps it one evaluation a fleet
   where f.player_id = v_player);
$h$),
  ('public.client_rpc_entry_points()'::text, 1, $h$      ('world',       'ship_moves',            'uuid'),
$h$, $h$      ('world',       'ship_moves',            'uuid'),
      -- 0354: the room a company has and how more opens; one step of room bought (dark until fleet_room_bite); a fleet renamed.
      ('world',       'house_room',            ''),
      ('cmd',         'buy_room',              'text'),
      ('cmd',         'rename_fleet',          'uuid, text'),
$h$)
), d as (
  select f.fn, replace(pg_get_functiondef(to_regprocedure(f.fn)), E'\r', '') as def,
         (select md5(coalesce(p.proacl::text, '') || p.provolatile::text || p.prosecdef::text || coalesce(p.proconfig::text, '')) from pg_proc p where p.oid = to_regprocedure(f.fn)) as attr_md5
    from (select distinct h.fn from h) f
), x as (
  select h.fn, h.ord,
         (length(d.def) - length(replace(d.def, h.old, ''))) / length(h.old) as old_times,
         (length(d.def) - length(replace(d.def, h.new, ''))) / length(h.new) as new_times
    from h join d on d.fn = h.fn
)
select jsonb_build_object(
  'head', (select max(version) from supabase_migrations.schema_migrations),
  'hunks', (select jsonb_agg(jsonb_build_object('fn', x.fn, 'ord', x.ord, 'old_times', x.old_times, 'new_times', x.new_times) order by x.fn, x.ord) from x),
  'attrs', (select jsonb_object_agg(d.fn, d.attr_md5) from d),
  'fleet_room_bite', (select c.value from public.world_config c where c.key = 'fleet_room_bite'),
  'knobs', (select jsonb_object_agg(c.key, c.value) from public.world_config c where c.key in ('fleet_room_prices', 'ship_room_prices', 'fleet_room_levels', 'fleet_hard_max', 'fleet_ship_top', 'fleet_max', 'fleet_ship_base', 'fleet_ship_max', 'ship_max', 'skill_max_level')),
  'house_room_rows', (select count(*) from public.house_room),
  'slot_word', (select jsonb_build_object('side', w.side, 'word', w.word, 'ord', w.ord) from public.stats_flow_words w where w.kind = 'SLOT'),
  'ord_56_is', (select w.kind from public.stats_flow_words w where w.ord = 56),
  'removed_kinds', (select coalesce(jsonb_agg(w.kind order by w.kind), '[]'::jsonb) from public.stats_flow_words w where w.side = 'removed'),
  'economy_closed', (select c.value from public.world_config c where c.key = 'economy_closed'),
  'made', jsonb_build_object(
    'public.fleet_totals(uuid,jsonb)', to_regprocedure('public.fleet_totals(uuid,jsonb)')::text,
    'public.room_steps(jsonb,integer,jsonb,jsonb,integer,boolean,bigint)', to_regprocedure('public.room_steps(jsonb,integer,jsonb,jsonb,integer,boolean,bigint)')::text,
    'world.house_room()', to_regprocedure('world.house_room()')::text,
    'public.buy_room_for(uuid,text)', to_regprocedure('public.buy_room_for(uuid,text)')::text,
    'cmd.buy_room(text)', to_regprocedure('cmd.buy_room(text)')::text,
    'public.rename_fleet(uuid,uuid,text)', to_regprocedure('public.rename_fleet(uuid,uuid,text)')::text,
    'cmd.rename_fleet(uuid,text)', to_regprocedure('cmd.rename_fleet(uuid,text)')::text),
  'premises', jsonb_build_object(
    'house_room_0321', to_regclass('public.house_room') is not null,
    'fleet_room_caps_0321', to_regprocedure('public.fleet_room_caps(uuid)') is not null,
    'fleet_wage_0154', to_regprocedure('public.fleet_wage(uuid,boolean,integer)') is not null,
    'refused_envelope_0123', to_regprocedure('cmd.refused_envelope(text,text)') is not null,
    'client_write_grants', to_regprocedure('public.client_write_grants()') is not null,
    'barca', exists (select 1 from public.ship_classes c where c.code = 'barca'),
    'lisbon', exists (select 1 from public.ports p where p.code = 'LIS'),
    'portugal_takes_companies', exists (select 1 from public.great_powers g join public.nations n on n.id = g.nation_id where n.code = 'PRT'),
    'probe_names_free', not exists (select 1 from public.players p where p.company_name like 'Casa % 0354'))
) as before_0354;
commit;
